import {toXY,inPolygon,metres} from './marine-geometry.mjs?v=carlights-20261127';
import {DATARAN_RING} from './dataran-layout.mjs?v=carlights-20261127';
export const INTERACTION_RADIUS=32;
const polygon=ring=>{const points=ring.map(([lng,lat])=>toXY([lat,lng]));return {points,minX:Math.min(...points.map(p=>p[0])),maxX:Math.max(...points.map(p=>p[0])),minY:Math.min(...points.map(p=>p[1])),maxY:Math.max(...points.map(p=>p[1]))}};
function edgeDistance(point,ring){const p=toXY(point),poly=polygon(ring);if(inPolygon(p,poly))return 0;let distance=Infinity;for(let n=1;n<poly.points.length;n++){const a=poly.points[n-1],b=poly.points[n],dx=b[0]-a[0],dy=b[1]-a[1],q=Math.max(0,Math.min(1,((p[0]-a[0])*dx+(p[1]-a[1])*dy)/(dx*dx+dy*dy||1)));distance=Math.min(distance,Math.hypot(p[0]-a[0]-q*dx,p[1]-a[1]-q*dy))}return distance}
export function createTownInteractions(places,environment=null){
 const buildings=new Map((environment?.features||[]).filter(f=>f.properties?.kind==='building'&&f.geometry?.type==='Polygon').map(f=>[f.properties.osm,f.geometry.coordinates[0]]));
 const entries=places.filter(p=>typeof p.properties?.osm==='string'&&p.geometry?.type==='Point'&&p.geometry.coordinates?.length===2&&p.geometry.coordinates.every(Number.isFinite)).map(place=>({place,ring:place.properties.kind==='plaza'?DATARAN_RING:buildings.get(place.properties.osm)}));
 return {nearby(position,radius=INTERACTION_RADIUS){if(!Array.isArray(position)||position.length!==2||!position.every(Number.isFinite))return [];return entries.map(({place,ring})=>({place,distance:ring?edgeDistance(position,ring):metres(position,[place.geometry.coordinates[1],place.geometry.coordinates[0]])})).filter(o=>o.distance<=radius).sort((a,b)=>a.distance-b.distance||a.place.properties.osm.localeCompare(b.place.properties.osm)).slice(0,5)}};
}
export function townInteractionCard(place){
 const p=place.properties,name=p.name,labels={plaza:'Dataran',landmark:'Monumen',police:'Kemudahan polis',office:'Pejabat & perkhidmatan',shop:'Premis perniagaan',civic:'Kemudahan awam'},card={name,label:labels[p.kind]||'Tempat bandar',intro:'Kenali tempat ini melalui peta bandar Labuan.',facts:[],observe:'Perhatikan bangunan, jalan dan ruang awam di sekeliling lokasi ini.'};
 if(p.kind==='plaza')return {...card,intro:'Ruang lapang di tengah bandar untuk dikenali semasa jelajah.',facts:['Padang tengah dibiarkan terbuka tanpa pokok.','Grandstand berada di tepi padang. Monumen di hujung barat mempunyai tiang bendera di tengah pelantarnya.'],observe:'Cari grandstand dan monumen di pinggir padang. Perhatikan perbezaan antara ruang padang dan laluan di sekelilingnya.'};
 if(name==='Bulatan Merdeka')return {...card,intro:'Bulatan utama dengan empat struktur payung jejaring yang tersendiri.',facts:['Empat struktur mempunyai tiang bercorak hitam-putih dan kanopi jejaring.','Pancutan air, rumput dan laluan mengisi ruang bulatan.'],observe:'Lihat keempat-empat kanopi dan corak jejaringnya dari sudut yang berbeza.'};
 if(name==='Monumen Ikan Marlin')return {...card,intro:'Arca ikan marlin menjadi tumpuan pada bulatan ini.',facts:['Reka bentuk memadankan arca ikan dan bentuk ombak.','Monumen diletakkan di atas tapak bertingkat di tengah bulatan.'],observe:'Cari bentuk muncung ikan marlin, sirip dan susunan arca di atas tapak.'};
 if(p.referenceFloors)return {...card,intro:'Menara Perbadanan Labuan menjadi salah satu mercu bangunan bandar.',facts:['Model menara mempunyai 11 tingkat mengikut gambar rujukan.','Fasad memadankan dinding putih/perak dengan jalur kaca biru gelap.'],observe:'Bandingkan sisi berjalur kaca dengan sisi dinding putih penuh.'};
 if(p.tags?.tourism==='museum')return {...card,intro:'Data peta mengenal pasti lokasi ini sebagai muzium.',facts:['Muzium ialah sebahagian daripada kemudahan budaya dan pendidikan bandar.'],observe:'Perhatikan bentuk bangunan dan hubungannya dengan ruang awam yang berdekatan.'};
 const copy={police:['Lokasi ini dikenal pasti sebagai kemudahan polis dalam data peta.','Perhatikan kedudukan kompleks dan aksesnya dari rangkaian jalan bandar.'],office:['Lokasi ini dikenal pasti sebagai pejabat atau pusat perkhidmatan dalam data peta.','Bandingkan bentuk pejabat dengan deretan kedai di sekelilingnya.'],shop:['Lokasi ini dikenal pasti sebagai premis perniagaan dalam data peta.','Perhatikan muka kedai dan susunan premis di sepanjang jalan.'],civic:['Lokasi ini dikenal pasti sebagai kemudahan awam dalam data peta.','Perhatikan akses bangunan dan ruang untuk orang ramai di sekelilingnya.']}[p.kind];
 if(copy){card.intro=copy[0];card.observe=copy[1];card.facts=['Kategori pada peta: '+card.label+'.'];if(p.tags?.operator)card.facts.push('Operator pada peta: '+p.tags.operator+'.');if(p.tags?.brand)card.facts.push('Jenama pada peta: '+p.tags.brand+'.')}return card;
}
